-- Demonstrating transaction isolation and non-blocking reads in PostgreSQL
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;

-- This query establishes a Read View snapshot.
-- Even if another concurrent transaction updates and commits changes to this table,
-- this transaction will continue to see the exact data state as of transaction start.
SELECT id, balance FROM accounts WHERE account_type = 'CHECKING';

COMMIT;
